contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking parameters to drive c.forward
    function run(address callee, bytes calldata data, uint256 amount) public payable {
        // ensure we have funds if we plan to send Ether to c
        require(address(this).balance >= amount);

        // observe balance of c before the call
        uint256 before = address(c).balance;

        // perform the forward call, sending `amount` wei along with it
        bool reverted;
        try c.forward{value: amount}(callee, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe balance of c after the call
        uint256 after = address(c).balance;

        // General rule asserted:
        // If the call to forward did not revert, then c's balance must have increased by exactly the amount we forwarded.
        // If the call reverted, then c's balance must be unchanged (no Ether moved into c on revert).
        assert((!reverted && after == before + amount) || (reverted && after == before));
    }

    // allow receiving Ether if needed by tests
    receive() external payable { }
}

