contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // The property: if a call to c.forward(callee,data) succeeds once (doesn't revert),
    // then calling it again with the same parameters from the same caller must also succeed.
    // We express this by attempting the first call and recording whether it reverted,
    // then attempting the second call and asserting that: if first succeeded then second also succeeds.

    function run(address callee, bytes memory data) public payable {
        require(true);

        bool firstReverted;
        bool secondReverted;

        // First attempt
        try c.forward(callee, data) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        // Second attempt (same caller, same params)
        try c.forward(callee, data) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        // General rule: if the first call succeeded, the second must also succeed.
        assert(!(firstReverted == false && secondReverted == true));
    }

    receive() external payable {}
}

