contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We cannot call any non-existent getter; owner is not public in C's source here,
    // so we observe owner by attempting to call a view function that would return it.
    // However C provides no such function, so instead we enforce that repeated calls
    // to forward do not change address(c) (which is immutable) — but that's trivial.
    // The original intended rule referenced owner; to express an observable invariant
    // we check that calling forward does not change C's balance and that calling it
    // twice with same inputs leads to the same success/revert behavior (determinism).

    // Single public function holding test logic
    function run(address callee, bytes memory data) public payable {
        require(true);
        // Record C's balance before
        uint256 balBefore = address(c).balance;
        bool firstReverted;
        try c.forward(callee, data) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }
        uint256 balAfterFirst = address(c).balance;
        // Call again with same inputs to check that the observable outcome (revert vs success)
        // is the same and that balance remains unchanged across both calls.
        bool secondReverted;
        try c.forward(callee, data) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        uint256 balAfterSecond = address(c).balance;
        // General rule: C's balance does not change across these calls and the success/revert
        // outcome is deterministic for the same inputs in this transaction.
        assert(balBefore == balAfterFirst && balAfterFirst == balAfterSecond && firstReverted == secondReverted);
    }

    receive() external payable {}
}

